/* calc: 64-bit integer expression evaluator. See the "calc" section of SPEC.md. */

#include "calc/calc.h"

#include <inttypes.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "calc/eval.h"

enum { READ_CHUNK = 64 * 1024 };

/*
 * Buffered line reader over a stream. Lines may be arbitrarily long; the
 * buffer grows to hold the longest one.
 */
struct line_reader {
    FILE *fp;
    char *buf;
    size_t cap;
    size_t start;  /* first unconsumed byte */
    size_t end;    /* one past the last byte read */
    size_t scan;   /* bytes in [start, scan) are known to hold no '\n' */
    bool eof;
};

/* Ensures at least READ_CHUNK bytes of free space after buf[end]. */
static bool reader_make_room(struct line_reader *r)
{
    if (r->start > 0) {
        size_t n = r->end - r->start;
        memmove(r->buf, r->buf + r->start, n);
        r->scan -= r->start;
        r->end = n;
        r->start = 0;
    }
    if (r->cap - r->end >= READ_CHUNK)
        return true;

    size_t new_cap = r->cap ? r->cap : READ_CHUNK;
    while (new_cap - r->end < READ_CHUNK) {
        if (new_cap > SIZE_MAX / 2)
            return false;
        new_cap *= 2;
    }
    char *p = realloc(r->buf, new_cap);
    if (!p)
        return false;
    r->buf = p;
    r->cap = new_cap;
    return true;
}

/*
 * Reads the next line, without its '\n', into *line / *len. Returns 1 on
 * success, 0 at end of input and -1 on a read or allocation error.
 */
static int reader_next(struct line_reader *r, const char **line, size_t *len)
{
    for (;;) {
        char *nl = r->scan < r->end
                       ? memchr(r->buf + r->scan, '\n', r->end - r->scan)
                       : NULL;
        if (nl) {
            size_t pos = (size_t)(nl - r->buf);
            *line = r->buf + r->start;
            *len = pos - r->start;
            r->start = r->scan = pos + 1;
            return 1;
        }
        r->scan = r->end;

        if (r->eof) {
            if (r->start == r->end)
                return 0;
            *line = r->buf + r->start; /* final line without '\n' */
            *len = r->end - r->start;
            r->start = r->scan = r->end;
            return 1;
        }

        if (!reader_make_room(r))
            return -1;
        size_t n = fread(r->buf + r->end, 1, r->cap - r->end, r->fp);
        r->end += n;
        if (n == 0) {
            if (ferror(r->fp))
                return -1;
            r->eof = true;
        }
    }
}

int calc_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    static char outbuf[64 * 1024];
    setvbuf(stdout, outbuf, _IOFBF, sizeof outbuf);

    struct line_reader reader = { .fp = stdin };
    struct calc_evaluator ev = CALC_EVALUATOR_INIT;
    const char *line;
    size_t len;
    int status = 0;
    int rc;

    while ((rc = reader_next(&reader, &line, &len)) > 0) {
        int64_t value;
        enum calc_status st = calc_eval(&ev, line, len, &value);
        if (st == CALC_OK) {
            printf("%" PRId64 "\n", value);
        } else if (st == CALC_ERROR) {
            fputs("error\n", stdout);
        } else if (st == CALC_NOMEM) {
            fputs("calc: out of memory\n", stderr);
            status = 1;
            break;
        }
    }
    if (rc < 0) {
        fputs(ferror(stdin) ? "calc: read error\n" : "calc: out of memory\n", stderr);
        status = 1;
    }

    calc_evaluator_free(&ev);
    free(reader.buf);

    if (fflush(stdout) == EOF || ferror(stdout)) {
        fputs("calc: write error\n", stderr);
        status = 1;
    }
    return status;
}

/* calc: 64-bit integer expression evaluator. See the "calc" section of SPEC.md. */
#ifndef CALC_H
#define CALC_H

/*
 * Runs the subcommand. argv[0] is "calc"; argv[1..argc-1] are any further
 * arguments. Reads standard input, writes standard output, and returns the
 * process exit status.
 */
int calc_main(int argc, char **argv);

#endif

/*
 * Operator-precedence (shunting-yard) evaluator for the calc grammar:
 *
 *   expr    := term    (('+' | '-') term)*
 *   term    := unary   (('*' | '/' | '%') unary)*
 *   unary   := '-' unary | primary
 *   primary := NUMBER | '(' expr ')'
 *
 * Explicit stacks are used instead of recursion so that deeply nested input
 * cannot overflow the call stack. Operators are applied as soon as they are
 * reduced, so evaluation stops at the first error.
 */

#include "calc/eval.h"

#include <stdbool.h>
#include <stdlib.h>

/* Operator stack entries. Binary operators are stored as their character. */
enum {
    OP_LPAREN = '(',
    OP_NEG = 'n',
};

static int precedence(unsigned char op)
{
    switch (op) {
    case '+': case '-':           return 1;
    case '*': case '/': case '%': return 2;
    case OP_NEG:                  return 3;
    default:                      return 0; /* '(' is never reduced past */
    }
}

/* Overflow-checked arithmetic. Each returns false if the result is undefined. */

static bool checked_add(int64_t a, int64_t b, int64_t *r)
{
    if ((b > 0 && a > INT64_MAX - b) || (b < 0 && a < INT64_MIN - b))
        return false;
    *r = a + b;
    return true;
}

static bool checked_sub(int64_t a, int64_t b, int64_t *r)
{
    if ((b < 0 && a > INT64_MAX + b) || (b > 0 && a < INT64_MIN + b))
        return false;
    *r = a - b;
    return true;
}

static bool checked_mul(int64_t a, int64_t b, int64_t *r)
{
    if (a > 0) {
        if (b > 0 ? a > INT64_MAX / b : b < INT64_MIN / a)
            return false;
    } else if (a < 0) {
        if (b > 0 ? a < INT64_MIN / b : b < INT64_MAX / a)
            return false;
    }
    *r = a * b;
    return true;
}

static bool checked_div(int64_t a, int64_t b, int64_t *r)
{
    if (b == 0 || (a == INT64_MIN && b == -1))
        return false;
    *r = a / b;
    return true;
}

static bool checked_rem(int64_t a, int64_t b, int64_t *r)
{
    if (b == 0)
        return false;
    *r = b == -1 ? 0 : a % b; /* INT64_MIN % -1 is undefined in C but 0 here */
    return true;
}

static bool checked_neg(int64_t a, int64_t *r)
{
    if (a == INT64_MIN)
        return false;
    *r = -a;
    return true;
}

/* Grows *buf (of elements of size elem) so that it can hold one more item. */
static bool reserve_one(void **buf, size_t *cap, size_t n, size_t elem)
{
    if (n < *cap)
        return true;
    size_t new_cap = *cap ? *cap * 2 : 64;
    if (new_cap > SIZE_MAX / elem)
        return false;
    void *p = realloc(*buf, new_cap * elem);
    if (!p)
        return false;
    *buf = p;
    *cap = new_cap;
    return true;
}

static bool push_val(struct calc_evaluator *ev, int64_t v)
{
    void *buf = ev->vals;
    if (!reserve_one(&buf, &ev->vals_cap, ev->nvals, sizeof *ev->vals))
        return false;
    ev->vals = buf;
    ev->vals[ev->nvals++] = v;
    return true;
}

static bool push_op(struct calc_evaluator *ev, unsigned char op)
{
    void *buf = ev->ops;
    if (!reserve_one(&buf, &ev->ops_cap, ev->nops, sizeof *ev->ops))
        return false;
    ev->ops = buf;
    ev->ops[ev->nops++] = op;
    return true;
}

/*
 * Pops the top operator and applies it to the operand stack. The parser only
 * reduces after a complete operand, so the required operands are present.
 */
static bool reduce(struct calc_evaluator *ev)
{
    unsigned char op = ev->ops[--ev->nops];
    int64_t *top = &ev->vals[ev->nvals - 1];

    if (op == OP_NEG)
        return checked_neg(*top, top);

    int64_t b = *top;
    int64_t *a = top - 1;
    ev->nvals--;
    switch (op) {
    case '+': return checked_add(*a, b, a);
    case '-': return checked_sub(*a, b, a);
    case '*': return checked_mul(*a, b, a);
    case '/': return checked_div(*a, b, a);
    case '%': return checked_rem(*a, b, a);
    default:  return false;
    }
}

/* Reduces every operator above the innermost '(' with precedence >= prec. */
static bool reduce_while(struct calc_evaluator *ev, int prec)
{
    while (ev->nops > 0 && ev->ops[ev->nops - 1] != OP_LPAREN &&
           precedence(ev->ops[ev->nops - 1]) >= prec) {
        if (!reduce(ev))
            return false;
    }
    return true;
}

static bool is_blank(char c)
{
    return c == ' ' || c == '\t';
}

static bool is_digit(char c)
{
    return c >= '0' && c <= '9';
}

enum calc_status calc_eval(struct calc_evaluator *ev, const char *line,
                           size_t len, int64_t *result)
{
    const char *p = line;
    const char *end = line + len;
    bool want_operand = true; /* else an operator or ')' is expected */
    bool any_token = false;

    ev->nvals = 0;
    ev->nops = 0;

    for (;;) {
        while (p < end && is_blank(*p))
            p++;
        if (p == end)
            break;
        any_token = true;
        char c = *p++;

        if (want_operand) {
            if (is_digit(c)) {
                int64_t v = c - '0';
                while (p < end && is_digit(*p)) {
                    int d = *p++ - '0';
                    if (v > (INT64_MAX - d) / 10)
                        return CALC_ERROR;
                    v = v * 10 + d;
                }
                if (!push_val(ev, v))
                    return CALC_NOMEM;
                want_operand = false;
            } else if (c == '(' || c == '-') {
                if (!push_op(ev, c == '(' ? OP_LPAREN : OP_NEG))
                    return CALC_NOMEM;
            } else {
                return CALC_ERROR;
            }
            continue;
        }

        switch (c) {
        case '+': case '-': case '*': case '/': case '%':
            if (!reduce_while(ev, precedence((unsigned char)c)))
                return CALC_ERROR;
            if (!push_op(ev, (unsigned char)c))
                return CALC_NOMEM;
            want_operand = true;
            break;
        case ')':
            if (!reduce_while(ev, 0))
                return CALC_ERROR;
            if (ev->nops == 0)
                return CALC_ERROR; /* unmatched ')' */
            ev->nops--;            /* pop the matching '(' */
            break;
        default:
            return CALC_ERROR;
        }
    }

    if (!any_token)
        return CALC_BLANK;
    if (want_operand)
        return CALC_ERROR; /* missing operand */
    if (!reduce_while(ev, 0))
        return CALC_ERROR;
    if (ev->nops != 0)
        return CALC_ERROR; /* unmatched '(' */

    *result = ev->vals[0];
    return CALC_OK;
}

void calc_evaluator_free(struct calc_evaluator *ev)
{
    free(ev->vals);
    free(ev->ops);
    *ev = (struct calc_evaluator)CALC_EVALUATOR_INIT;
}

/* Expression evaluator for calc: parses and evaluates one line. */
#ifndef CALC_EVAL_H
#define CALC_EVAL_H

#include <stddef.h>
#include <stdint.h>

enum calc_status {
    CALC_OK,     /* the expression has a value */
    CALC_BLANK,  /* the line holds only spaces and tabs */
    CALC_ERROR,  /* syntax error, division by zero or overflow */
    CALC_NOMEM,  /* out of memory */
};

/*
 * Evaluator state. The operand and operator stacks are kept between calls so
 * that their storage is reused; nesting depth is limited only by memory.
 * Initialise with CALC_EVALUATOR_INIT and release with calc_evaluator_free().
 */
struct calc_evaluator {
    int64_t *vals;
    size_t nvals, vals_cap;
    unsigned char *ops;
    size_t nops, ops_cap;
};

#define CALC_EVALUATOR_INIT { NULL, 0, 0, NULL, 0, 0 }

/*
 * Evaluates the len bytes at line (which need not be NUL-terminated and must
 * not contain the line terminator). On CALC_OK stores the value in *result.
 */
enum calc_status calc_eval(struct calc_evaluator *ev, const char *line,
                           size_t len, int64_t *result);

void calc_evaluator_free(struct calc_evaluator *ev);

#endif

/*
 * lru/cache: hash table with separate chaining over a pool of nodes that are
 * also threaded on a circular doubly linked recency list. Nodes are addressed
 * by 32-bit index so the pool can be grown with realloc; index 0 is the list
 * sentinel and doubles as the "no node" value in hash chains and the free list.
 *
 * List order: sentinel.next is the most recently used entry, sentinel.prev
 * the least recently used.
 */

#include "lru/cache.h"

#include <stdlib.h>
#include <string.h>

#define NIL 0u
#define SENTINEL 0u
#define INITIAL_NODES 1024u

struct lru_node {
    const char *key;
    const char *value;
    uint32_t hash;
    uint32_t prev;
    uint32_t next;
    uint32_t chain;     /* next node in the same hash bucket */
    uint8_t key_len;
    uint8_t value_len;
};

/* FNV-1a, followed by a final avalanche so the low bits used as the bucket
 * index depend on every input byte. */
static uint32_t hash_key(const char *key, size_t len)
{
    uint64_t h = 0xcbf29ce484222325u;
    for (size_t i = 0; i < len; i++) {
        h ^= (unsigned char)key[i];
        h *= 0x100000001b3u;
    }
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdu;
    h ^= h >> 33;
    return (uint32_t)h;
}

static void list_unlink(struct lru_node *nodes, uint32_t i)
{
    nodes[nodes[i].prev].next = nodes[i].next;
    nodes[nodes[i].next].prev = nodes[i].prev;
}

static void list_push_front(struct lru_node *nodes, uint32_t i)
{
    uint32_t first = nodes[SENTINEL].next;
    nodes[i].prev = SENTINEL;
    nodes[i].next = first;
    nodes[first].prev = i;
    nodes[SENTINEL].next = i;
}

static void list_move_front(struct lru_node *nodes, uint32_t i)
{
    if (nodes[SENTINEL].next != i) {
        list_unlink(nodes, i);
        list_push_front(nodes, i);
    }
}

/*
 * Finds `key` and returns its node index, or NIL. If `link` is non-NULL it
 * receives the address of the chain link pointing at the result (or at the
 * end of the chain on a miss), so the caller can splice the node out.
 */
static uint32_t table_find(const struct lru_cache *c, const char *key,
                           size_t len, uint32_t hash, uint32_t **link)
{
    uint32_t *p = &c->buckets[hash & c->bucket_mask];
    while (*p != NIL) {
        const struct lru_node *n = &c->nodes[*p];
        if (n->hash == hash && n->key_len == len &&
            memcmp(n->key, key, len) == 0)
            break;
        p = &c->nodes[*p].chain;
    }
    if (link)
        *link = p;
    return *p;
}

static void table_insert(struct lru_cache *c, uint32_t i)
{
    uint32_t *bucket = &c->buckets[c->nodes[i].hash & c->bucket_mask];
    c->nodes[i].chain = *bucket;
    *bucket = i;
}

static void table_remove(struct lru_cache *c, uint32_t i)
{
    const struct lru_node *n = &c->nodes[i];
    uint32_t *link;
    table_find(c, n->key, n->key_len, n->hash, &link);
    *link = n->chain;
}

/* Grows the bucket array to `count` (a power of two) and rehashes. */
static bool table_resize(struct lru_cache *c, uint32_t count)
{
    uint32_t *buckets = calloc(count, sizeof *buckets);
    if (!buckets)
        return false;
    free(c->buckets);
    c->buckets = buckets;
    c->bucket_mask = count - 1;
    for (uint32_t i = c->nodes[SENTINEL].next; i != SENTINEL; i = c->nodes[i].next)
        table_insert(c, i);
    return true;
}

static uint32_t round_up_pow2(uint32_t n)
{
    uint32_t p = 1;
    while (p < n)
        p <<= 1;
    return p;
}

/* Returns a free node slot, growing the pool (and the table with it) if
 * needed, or NIL if memory is exhausted. */
static uint32_t node_alloc(struct lru_cache *c)
{
    if (c->free_list != NIL) {
        uint32_t i = c->free_list;
        c->free_list = c->nodes[i].next;
        return i;
    }
    if (c->node_used == c->node_cap) {
        uint32_t limit = c->capacity + 1;
        uint32_t cap = c->node_cap > limit / 2 ? limit : c->node_cap * 2;
        struct lru_node *nodes = realloc(c->nodes, (size_t)cap * sizeof *nodes);
        if (!nodes)
            return NIL;
        c->nodes = nodes;
        c->node_cap = cap;
    }
    if (c->node_used > c->bucket_mask + 1 &&
        !table_resize(c, (c->bucket_mask + 1) * 2))
        return NIL;
    return c->node_used++;
}

static void node_free(struct lru_cache *c, uint32_t i)
{
    c->nodes[i].next = c->free_list;
    c->free_list = i;
}

bool lru_cache_init(struct lru_cache *c, size_t capacity)
{
    memset(c, 0, sizeof *c);
    if (capacity < 1 || capacity > LRU_CACHE_MAX_CAPACITY)
        return false;

    c->capacity = (uint32_t)capacity;
    c->node_cap = c->capacity < INITIAL_NODES ? c->capacity + 1 : INITIAL_NODES;
    c->nodes = malloc((size_t)c->node_cap * sizeof *c->nodes);
    uint32_t nbuckets = round_up_pow2(c->node_cap);
    c->buckets = calloc(nbuckets, sizeof *c->buckets);
    if (!c->nodes || !c->buckets) {
        lru_cache_destroy(c);
        return false;
    }
    c->bucket_mask = nbuckets - 1;
    c->nodes[SENTINEL].prev = SENTINEL;
    c->nodes[SENTINEL].next = SENTINEL;
    c->node_used = 1;
    return true;
}

void lru_cache_destroy(struct lru_cache *c)
{
    free(c->nodes);
    free(c->buckets);
    memset(c, 0, sizeof *c);
}

bool lru_cache_get(struct lru_cache *c, const char *key, size_t key_len,
                   const char **value, size_t *value_len)
{
    uint32_t i = table_find(c, key, key_len, hash_key(key, key_len), NULL);
    if (i == NIL)
        return false;
    list_move_front(c->nodes, i);
    *value = c->nodes[i].value;
    *value_len = c->nodes[i].value_len;
    return true;
}

bool lru_cache_set(struct lru_cache *c, const char *key, size_t key_len,
                   const char *value, size_t value_len)
{
    uint32_t hash = hash_key(key, key_len);
    uint32_t i = table_find(c, key, key_len, hash, NULL);

    if (i != NIL) {
        c->nodes[i].value = value;
        c->nodes[i].value_len = (uint8_t)value_len;
        list_move_front(c->nodes, i);
        return true;
    }

    if (c->size == c->capacity) {
        /* Full: recycle the least recently used entry's slot. */
        i = c->nodes[SENTINEL].prev;
        table_remove(c, i);
        list_unlink(c->nodes, i);
        c->size--;
    } else {
        i = node_alloc(c);
        if (i == NIL)
            return false;
    }

    struct lru_node *n = &c->nodes[i];
    n->key = key;
    n->key_len = (uint8_t)key_len;
    n->value = value;
    n->value_len = (uint8_t)value_len;
    n->hash = hash;
    table_insert(c, i);
    list_push_front(c->nodes, i);
    c->size++;
    return true;
}

bool lru_cache_del(struct lru_cache *c, const char *key, size_t key_len)
{
    uint32_t *link;
    uint32_t i = table_find(c, key, key_len, hash_key(key, key_len), &link);
    if (i == NIL)
        return false;
    *link = c->nodes[i].chain;
    list_unlink(c->nodes, i);
    node_free(c, i);
    c->size--;
    return true;
}

size_t lru_cache_size(const struct lru_cache *c)
{
    return c->size;
}

/*
 * lru/cache: a fixed-capacity LRU map from byte-string keys to byte-string
 * values, with O(1) expected time per operation.
 *
 * The cache does not copy keys or values: it stores the caller's pointers,
 * so the bytes they point to must stay valid and unchanged for as long as
 * the cache may refer to them (until the entry is overwritten, deleted or
 * evicted, or the cache is destroyed).
 */
#ifndef LRU_CACHE_H
#define LRU_CACHE_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Longest key or value the cache accepts, in bytes. */
#define LRU_CACHE_MAX_LEN 255u

/* Largest supported capacity. */
#define LRU_CACHE_MAX_CAPACITY (UINT32_MAX / 4u)

struct lru_node;

struct lru_cache {
    struct lru_node *nodes;   /* nodes[0] is the sentinel of the recency list */
    uint32_t *buckets;        /* hash chains of node indices; 0 ends a chain  */
    uint32_t bucket_mask;     /* bucket count - 1 (a power of two)            */
    uint32_t node_cap;        /* allocated slots in nodes, sentinel included  */
    uint32_t node_used;       /* slots ever handed out, sentinel included     */
    uint32_t free_list;       /* recycled slots linked by next; 0 if none     */
    uint32_t size;            /* live entries                                 */
    uint32_t capacity;        /* maximum live entries                         */
};

/*
 * Initialises an empty cache holding at most `capacity` entries
 * (1 ≤ capacity ≤ LRU_CACHE_MAX_CAPACITY). Returns false if the capacity
 * is out of range or memory is exhausted.
 */
bool lru_cache_init(struct lru_cache *cache, size_t capacity);

/* Releases all memory owned by the cache. */
void lru_cache_destroy(struct lru_cache *cache);

/*
 * Looks up `key`. On a hit, marks it most recently used, stores its value
 * in *value / *value_len and returns true; otherwise returns false.
 */
bool lru_cache_get(struct lru_cache *cache, const char *key, size_t key_len,
                   const char **value, size_t *value_len);

/*
 * Inserts or overwrites `key`, making it the most recently used entry and
 * evicting the least recently used one if the cache would exceed its
 * capacity. Both lengths must be at most LRU_CACHE_MAX_LEN. Returns false
 * only if memory is exhausted, in which case the cache is unchanged.
 */
bool lru_cache_set(struct lru_cache *cache, const char *key, size_t key_len,
                   const char *value, size_t value_len);

/* Removes `key`. Returns whether it was present. */
bool lru_cache_del(struct lru_cache *cache, const char *key, size_t key_len);

/* Returns the number of entries held. */
size_t lru_cache_size(const struct lru_cache *cache);

#endif

/* lru: LRU cache simulator. See the "lru" section of SPEC.md. */

#include "lru/lru.h"

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lru/cache.h"

#define CAPACITY_MAX 1000000u
#define TOKEN_MAX 64u
#define MAX_TOKENS 3

struct buffer {
    char *data;
    size_t len;
};

/*
 * Reads all of `in` into memory. The cache refers to keys and values in
 * place, so the whole input must outlive it. Returns false on a read or
 * allocation failure.
 */
static bool read_all(FILE *in, struct buffer *buf)
{
    size_t cap = 1 << 16;
    size_t len = 0;
    char *data = malloc(cap);
    if (!data)
        return false;

    for (;;) {
        if (len == cap) {
            char *grown = realloc(data, cap * 2);
            if (!grown) {
                free(data);
                return false;
            }
            data = grown;
            cap *= 2;
        }
        size_t n = fread(data + len, 1, cap - len, in);
        len += n;
        if (n == 0) {
            if (ferror(in)) {
                free(data);
                return false;
            }
            break;
        }
    }
    buf->data = data;
    buf->len = len;
    return true;
}

struct token {
    const char *s;
    size_t len;
};

/* Splits [s, s+len) on single spaces. Returns the token count, or -1 if
 * there are more than `max` tokens or any token is empty. */
static int split(const char *s, size_t len, struct token *tok, int max)
{
    int n = 0;
    const char *end = s + len;
    for (;;) {
        const char *sp = memchr(s, ' ', (size_t)(end - s));
        const char *stop = sp ? sp : end;
        if (stop == s || n == max)
            return -1;
        tok[n].s = s;
        tok[n].len = (size_t)(stop - s);
        n++;
        if (!sp)
            return n;
        s = sp + 1;
    }
}

static bool token_is(const struct token *t, const char *word)
{
    size_t len = strlen(word);
    return t->len == len && memcmp(t->s, word, len) == 0;
}

static bool parse_capacity(const char *s, size_t len, size_t *out)
{
    if (len == 0)
        return false;
    size_t v = 0;
    for (size_t i = 0; i < len; i++) {
        if (s[i] < '0' || s[i] > '9')
            return false;
        v = v * 10 + (size_t)(s[i] - '0');
        if (v > CAPACITY_MAX)
            return false;
    }
    if (v < 1)
        return false;
    *out = v;
    return true;
}

/* Returns the next line of [*pos, end) without its terminator ("\n" or
 * "\r\n") and advances *pos past it. */
static struct token next_line(const char **pos, const char *end)
{
    const char *s = *pos;
    const char *nl = memchr(s, '\n', (size_t)(end - s));
    const char *stop = nl ? nl : end;
    *pos = nl ? nl + 1 : end;
    if (stop > s && stop[-1] == '\r')
        stop--;
    return (struct token){ s, (size_t)(stop - s) };
}

/* Executes one command line, writing its output to `out`. Returns false if
 * the line is malformed. */
static bool run_command(struct lru_cache *cache, struct token line, FILE *out,
                        bool *oom)
{
    struct token tok[MAX_TOKENS];
    int n = split(line.s, line.len, tok, MAX_TOKENS);
    if (n < 1)
        return false;
    for (int i = 1; i < n; i++) {
        if (tok[i].len > TOKEN_MAX)
            return false;
    }

    if (n == 3 && token_is(&tok[0], "SET")) {
        if (!lru_cache_set(cache, tok[1].s, tok[1].len, tok[2].s, tok[2].len))
            *oom = true;
    } else if (n == 2 && token_is(&tok[0], "GET")) {
        const char *value;
        size_t value_len;
        if (lru_cache_get(cache, tok[1].s, tok[1].len, &value, &value_len)) {
            fwrite(value, 1, value_len, out);
            putc('\n', out);
        } else {
            fputs("NULL\n", out);
        }
    } else if (n == 2 && token_is(&tok[0], "DEL")) {
        fputs(lru_cache_del(cache, tok[1].s, tok[1].len) ? "1\n" : "0\n", out);
    } else if (n == 1 && token_is(&tok[0], "SIZE")) {
        fprintf(out, "%zu\n", lru_cache_size(cache));
    } else {
        return false;
    }
    return true;
}

int lru_main(int argc, char **argv)
{
    if (argc != 1) {
        fprintf(stderr, "usage: %s < input\n", argv[0]);
        return 2;
    }

    struct buffer input;
    if (!read_all(stdin, &input)) {
        fprintf(stderr, "%s: cannot read standard input\n", argv[0]);
        return 1;
    }

    const char *pos = input.data;
    const char *end = input.data + input.len;
    struct token first = next_line(&pos, end);
    size_t capacity;
    if (!parse_capacity(first.s, first.len, &capacity)) {
        fprintf(stderr, "%s: line 1: invalid capacity\n", argv[0]);
        free(input.data);
        return 1;
    }

    struct lru_cache cache;
    if (!lru_cache_init(&cache, capacity)) {
        fprintf(stderr, "%s: out of memory\n", argv[0]);
        free(input.data);
        return 1;
    }

    static char outbuf[1 << 16];
    setvbuf(stdout, outbuf, _IOFBF, sizeof outbuf);

    int status = 0;
    bool oom = false;
    for (size_t lineno = 2; pos < end && !oom; lineno++) {
        struct token line = next_line(&pos, end);
        if (line.len == 0)
            continue;
        if (!run_command(&cache, line, stdout, &oom))
            fprintf(stderr, "%s: line %zu: invalid command ignored\n",
                    argv[0], lineno);
    }
    if (oom) {
        fprintf(stderr, "%s: out of memory\n", argv[0]);
        status = 1;
    }
    if (fflush(stdout) != 0) {
        fprintf(stderr, "%s: write error\n", argv[0]);
        status = 1;
    }

    lru_cache_destroy(&cache);
    free(input.data);
    return status;
}

